  await expect(body('父事项')).toHaveJSProperty('hidden',true)
  await page.reload(); await expect(body('父事项')).toHaveJSProperty('hidden',true)
  await head(item(page,'父事项')).getByRole('button',{name:'展开',exact:true}).click()
  await expect(body('父事项')).toHaveJSProperty('hidden',false); await expect(body('子事项')).toHaveJSProperty('hidden',true)
  await named(page,head(item(page,'子事项')).getByRole('button',{name:'重命名事项',exact:true}),'改名子事项')
  await expect(body('改名子事项')).toHaveJSProperty('hidden',true)
