  await expect(item(page,'目标事项').locator('.item[data-item="改名子事项"]')).toHaveCount(1)
  await expect(body('改名子事项')).toHaveJSProperty('hidden',true)
  await named(page,page.getByRole('button',{name:'新增视图',exact:true}),'折叠视图乙')
  await named(page,area(page,'结果').getByRole('button',{name:'新增根事项',exact:true}),'改名子事项')
  await expect(body('改名子事项')).toHaveJSProperty('hidden',false)
